WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (445::BIGINT, 'Ella es muy ordenada, le gusta mucho los temas del curso. Hay que ir con la materia al día. Evite preguntar cosas que acaba de decir, responde pero con poco tacto. Si le pide ayuda siempre está dispuesta a colaborar. No es un curso pesado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros']::TEXT[], '2026-01-11T00:00:00+00:00'::TIMESTAMPTZ, '27f40383263f99b40bbd3849c061628646ee548329e85e59317c00db8c122065'::TEXT, ARRAY[1746]::BIGINT[]),
    (445::BIGINT, 'Es muy clara en sus clases y presentaciones. Es una muy buena opción para cualquier curso, suele ser seca y aveces grosera pero siempre busca que uno aprenda y le vaya bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Muchos exámenes']::TEXT[], '2025-12-22T00:00:00+00:00'::TIMESTAMPTZ, '281e36ee09a7e137622b8e0906e27e5ac44c0147f9cb69deb18bf90480be113d'::TEXT, ARRAY[1746]::BIGINT[]),
    (445::BIGINT, 'Es buena profesora, muy muy ordenada y clara para todo tipo de aspectos del curso. Las presentaciones son muy completas lo que ayuda a estudiar de manera autodidacta. Cuando responde preguntas si es grosera, en especial si es algo que acaba de decir. Es muy importante hacer los cálculos en clase.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '37187040c7f3736b210126eef765fcf9f9b10cda4e2ff90630340a4810f36fec'::TEXT, ARRAY[1742]::BIGINT[]),
    (445::BIGINT, 'Natalia es una profesora normal, con muy buen material. Si usted estudia las presentaciones y evaluaciones de semestres anteriores pasa. Es grosera con todo mundo, y cuando le preguntan en clase es repugnante, pero en consulta es buena y realmente busca aclarar. Buena opción para proba 2.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '0551d30b11e7cc3177dee2270d6b7bf2729ef71c96cfc161a661cfc22a55840d'::TEXT, ARRAY[1742]::BIGINT[]),
    (445::BIGINT, 'No entiendo cómo hay gente que dice que es fácil. Es un poco egocéntrica, si usted dice algo que no es como ella lo haría, se lo restriega en la cara. El curso fácil no es, pero no dependa de las explicaciones que ella da de la materia. No la llevaría otra vez con ella.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2025-06-06T00:00:00+00:00'::TIMESTAMPTZ, '738778561fe5bd57be65533a45ea956aadb8d20bcb0045362521f1eb2e89171c'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (445::BIGINT, 'Es sumamanete pesada, le gusta humillar a sus estudiantes dicen que esto le da fuerza para continuar con su plan de destruir al mundo. Fuera de broma, ella hace de los cursos bonitos, feos'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, '8b091d63f70305e6b0f6d90b2250b33d8af961d1c9a962c5e2eb54bc6a60ea14'::TEXT, ARRAY[1728, 1743, 1742]::BIGINT[]),
    (445::BIGINT, 'Es de las mejores de produ. Si uno no entiende algo en la clase de fijo revisando las presentaciones lo entiende. Hace quices y tareas todas las semanas, pero son súper útiles para ir al día y lo preparan para el examen. Califica suave. Hay que tomarse su personalidad en plan chill.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-23T00:00:00+00:00'::TIMESTAMPTZ, '4465dba95885b3c95ba5ce0a4fc50b248b9e9462f3aa642eabc778bcba071616'::TEXT, ARRAY[1742]::BIGINT[]),
    (445::BIGINT, 'En general esta bien, las presentaciones son un enrredo pero con un poco de paciencia se saca fácil'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2024-11-28T00:00:00+00:00'::TIMESTAMPTZ, '7c13269388c6c643147864efe24b2a245272d7a6a882dbb0419425f4f674dc18'::TEXT, ARRAY[1746]::BIGINT[]),
    (445::BIGINT, 'No es mala mala, simplemente es un poco pesada porque es egocentrica, entonces si usted hizo algo "tonto" en una evaluación se lo va a decir a jacha. La verdad las clases son aburridas porque solo lee la presentación, pero fuera de eso el curso se puede pasar bien'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2024-11-11T00:00:00+00:00'::TIMESTAMPTZ, '1698ef519494d87564de051d24d3b0564091a7d7d3a2758fdf380095d9431d1c'::TEXT, ARRAY[1746]::BIGINT[]),
    (445::BIGINT, 'Todas las semanas hay quices y tarea, pero son faciles y cortos, entonces es con llevar la materia medio al dia. Los examenes se hacen con formulario, puede poner lo que sea en ellos y la extension que sea, osea un queque. Se puede ir solo con hacer formularios y se saca buena nota.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, '7952579c0baeb867089484e59d065f96b60b60dbee4d275588d03ed6112dbcea'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'El curso es un poco tedioso pero no difícil. La profe lo hace todo un poco aburrido porque en las clases únicamente se leen presentaciones y en realidad eso se puede hacer individualmente en casa, lo bueno es que califica suave.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, '6e9c0446d10f96f9169a974626b33121e7e6274940ef6821e2390515913351a7'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (445::BIGINT, 'La profe habla mucho y solo lee presentaciones, pero el curso es sencillo y teórico, las evaluaciones suelen ser recicladas (de semestres anteriores) pero califica suave. Tenga un buen grupo de trabajo para el proyecto.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-07-11T00:00:00+00:00'::TIMESTAMPTZ, '4b0bfba4f5e869049d0f085db320b4bb986abff8dce7fd402c43b1759e2d6fc1'::TEXT, ARRAY[1791]::BIGINT[]),
    (445::BIGINT, 'Muy buena profe explica excelente y ayuda bastante en consulta. Súper recomendada deja bastantes tareas, pero prepara bien para los exámenes y deja dos proyectos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'e6ef8e07ca2cbb424fb8eb30b7cf854f5ec5ed430ea2b179aea9454224e2ae2d'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'Si, puede ser un poco grocera pero nada del otro mundo, es muy buena profe y explica muy bien. Deja tareas casi todas las semanas pero ayudan mucho a prepararse para los exámenes, los quices son muy fáciles. Califica bien y se pasa con buena nota.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'bbf95c942815f19e63a79017c5e9377fc00b43495a1bfbd7ccb1260868e11abe'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'El curso es fácil, y por eso mismo las clases se vuelven tediosas, lo recomendable es no tomar apuntes porque la profe va con presentaciones de power point que las sube al tec digital, únicamente haga las tareas y los ejercicios de clase para repasar. Con eso pasa el curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2022-11-24T00:00:00+00:00'::TIMESTAMPTZ, '979292c36cdad51bb50021fab6625c44e9483f7b4bab9af829845d467f3b1511'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (445::BIGINT, 'Lo malo: Es muy grosera. No acepta cuando se equivoca. Lo bueno: Explica EXCELENTE, todo muy claro. Todas las semanas deja tareas, los quices son muy sencillos y cortos. Los exámenes fueron fáciles con ejercicios muy similares a los quices. El curso se pasa fácil y con una buena nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'ac2b69995ec98a69604546ed957f2647dd37406bfcde7df8ab5809d1cf0b7965'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'Amanding. No es la persona más dulce del mundo, pero es súper buena profe y súper comprensiva.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'ee1eb7a52570375601efe9de92a98aca0e2a8b0cc2dacaec91f9a401ed4b1ebe'::TEXT, ARRAY[1728]::BIGINT[]),
    (445::BIGINT, 'Muy buena profe, de lo mejor que hay en la escuela, es estricta, los exámenes y tareas pueden ser difíciles, los cursos que ella da generalmente demandan mucho tiempo semanalmente para estudiar y salir con todas las asignaciones. Pero explica super bien, da las dotas a tiempo y aclara dudas'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, '8789bc6054a621a1449f25761c9858b770c47280397a668c2ebf9906f8cbd788'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (445::BIGINT, 'Excelente profesora. Llevaría más cursos así, era mi primer curso con ella. La recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'e6a2828eefc87fa1e1d3615c770b66faaf450790a98c61a33caa5152feb0940c'::TEXT, ARRAY[1746]::BIGINT[]),
    (445::BIGINT, 'Es muy buena explicando y deja bastantes tareas que facilitan entender la materia. Pero tenga claro que el trato al estudiante no es el mejor, puede llegar a ser muy grosera. Pero teniendo en cuenta que en la escuela de producción no hay buenos profes, es de lo mejorcito que hay.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '8cca34ab618390cbd5588321af9e69ff307083da787c998926b89eaa8f4bdde3'::TEXT, ARRAY[1746]::BIGINT[]),
    (445::BIGINT, 'Las clases son súper claras y da varios ejemplos para entender la materia. Todas las semanas hay tareas pero ayudan para tener la materia al día.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '4ead427e6f76f92af982d9aac62cc6b2958916cf78ddaab09a44e4fa1bc403d6'::TEXT, ARRAY[1746]::BIGINT[]),
    (445::BIGINT, 'En general es buena profe, ni mala ni excelente. A veces es un poquito grosera al responder las dudas en clases pero tampoco es nada del otro mundo. Muchas tareas pero son adecuadas al curso y ayudan a llevar la materia al día. La materia en sí es fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, '419c8734045e0a1485dbd039fe0714f34b2e09afbd44899ad63632bb717010a3'::TEXT, ARRAY[1728, 1743, 1742]::BIGINT[]),
    (445::BIGINT, 'Deja tareas casi que todas las semanas que son iguales a los quices y exámenes. Un problema que tiene la profe es la manera de dirigirse a los estudiantes, es muy descortés al punto que a uno ni le dan ganas de preguntarle nada. No considero que sea buena profe si no que el curso es muy fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '59b3449a9616b07c0c606b40157f5bfb15a8874b30176db72f8ae7bbb33a659e'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'Al inicio cuesta un toque acoplarse a como es la profe y la clase, pero uno le va agarrando el toque y se vuelve muy fácil. Ella tiene cierto carácter, no es enojo pero puede responder de mala manera a veces (creo que no lo hace al propio).Estudie con los videos, califica suave, muy buena la verdad'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'f18609849e7d0cd9b6b53a227477cb01cb852b23b8c5e784a3b60a8517a25731'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'No es mala profe sin embargo tiene problemas de enojo. No maneja el carácter y responde de mala manera a las cosas. Debería desahogarse o ir a terapia.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'db9d6bac4e5af4ddc200e356d2d99debc905f30c01ec739eaac24b2bdeac0d5a'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'La profe Natalia es excelente, en los dos cursos que llevé con ella (IO y proba) aprendí bastante. Las evaluaciones que deja (tareas, exámenes y proyectos) son muy útiles para tener una mejor compresión de los temas, además en consulta es muy accesible!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'f0c6f5dcf52658aba66a20ec2ef7da26614ea5218b41809f174509da310ba9df'::TEXT, ARRAY[1746, 1742]::BIGINT[]),
    (445::BIGINT, 'Para mí, esta profe debería tener una calificación de 10. He llevado 3 cursos con ella y me parece super buena profesora. Explica bastante bien, hace ejemplos y es muy accesible en consulta. En clase a veces no responde de buena forma las preguntas pero si las responde. En los 3 cursos me saque 100.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '4a603c6de1141d83d99204528bbda38333712cd29fa47e8ef7c2440a7e53ef2a'::TEXT, ARRAY[1728, 1769]::BIGINT[]),
    (445::BIGINT, 'Es buena explicando y sus presentaciones son un resumen del libro. Deja varias tareas pero son cortas y ayudan a tener la materia al día. Ayuda bastante en consulta. Lo único que la haría mejor es que sus examenes y proyectos fueran un poco más difíciles, porque todo el mundo saca nota muy alta.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'e603edfde7dca7cd974558fd2ebd9b2b04ebf18f5092fb6e1ea6c9f2e2cb2ca1'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'De las mejores profes de produ, muy ordenada, muy clara al explicar y da retroalimentación en un período bastante corto, al inicio deja tareas todas las semanas pero no son el fin del mundo. Es un poco grosera al atender dudas, pero igual las responde y explica las veces necesarias. Pasa lista.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'a125ab853defe0035427754bbe2039e57f6751c055da7fb2a4b7e8871b0950c8'::TEXT, ARRAY[1746]::BIGINT[]),
    (445::BIGINT, 'Excelente profe! En ambos cursos deja muchas tareas que es lo necesario para ir listo para el examen. Va a al grano y con solo prestar atencion a las clases y hacer las tareas va sobrado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'afb488b7040828c238627efc1d314fea2040643ddad5e019db72ec2e3895f563'::TEXT, ARRAY[1742, 1746]::BIGINT[]),
    (445::BIGINT, 'Natalia es muy buena profe, explica bastante bien y va al grano, hace muchas tareas pero así uno ni tiene que estudiar para el examen, califica todo muy rápido y da muy buena retroalimentación, de fijo llevaría lo que sea con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'f3592f3715870ce8d525c9bcf05b284dcf3ba18f4a271cb275c4af5a13a0e360'::TEXT, ARRAY[1742]::BIGINT[]),
    (445::BIGINT, 'Muy buena profe. Las clases sincrónicas se pueden volverse aburridas, es mejor verlas grabadas al momento de hacer las tareas semanales. Atiende las consultas y no califica duro en los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, '2ba2b6f119d39d8561af80889d06e992e0a8e57625312eb6d980ccecaf48c10d'::TEXT, ARRAY[1742]::BIGINT[]),
    (445::BIGINT, 'Natalia es de las mejores profes que tiene la escuela, además de ser muy buena persona :) Las clases generalmente son cortas, ella va al punto para que no se vuelva aburrido. Deja tareas todas las semanas en ambos cursos, pero eso es demasiado bueno porque uno lleva la materia al día.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-12T00:00:00+00:00'::TIMESTAMPTZ, '6cf0cdc6570029aeff55960befd68dc9e3a0fdad69f56a53f27d0dac8d4d142b'::TEXT, ARRAY[1746]::BIGINT[]),
    (445::BIGINT, 'La profe explica claro y en realidad la materia no es díficil. Hay tareas casi que todas las semanas pero son de lo mismo visto en clase, y los exámenes no son complicados. Para mí es una buena profe.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '768f5774ee6c4f39b65138d55e139d17a5c3a18e5e579a1bb03919c0c719cc44'::TEXT, ARRAY[1769]::BIGINT[]),
    (445::BIGINT, 'Las presentaciones son super claras, pero ella se enrreda un toque para explicar. Sin embargo uno siempre entiende la materia por las tareas que son todas las semanas. Ayuda mucho y responde rápido cuando uno tiene dudas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '8a9e3ae841a863bbfa1281aabc626776b8f6e6805b957ba2e5d30380312cb0ea'::TEXT, ARRAY[1769]::BIGINT[]),
    (445::BIGINT, 'Muy buena profe, explica muy bien y las presentaciones ayudan bastante. Da muy buena retroalimentación en los proyectos. Los quices y exámenes (virtualmente) son fáciles.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'd7fd7e97e2e4b7990f4baa663e432c4bf06a6803f8a48f7b3b48a40f96ae6393'::TEXT, ARRAY[1746]::BIGINT[]),
    (445::BIGINT, 'Es buena profesora y excelente explicando pero parece que le tiene cierta idea a los estudiantes. Tareas todas las semanas lo que lo obliga a uno a llevar la materia al día, en mod. virtual las clases no son largas, pocos quices pero sus exámenes son bastante largos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'c14b30892fc873ad92e0a4bcad88dc7a7557c25f4cb809c998e25fc4122f6259'::TEXT, ARRAY[1746]::BIGINT[]),
    (445::BIGINT, 'Es una muy buena profe, hay que tenerle paciencia, porque es medio diferente jajaj, pero es bastante sencillo y las presentaciones que ella sube es lo necesario para los exámenes que no son para nada complicados si uno hace todas las tareas que deja, ayuda bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, '1fd4762e0f83fbb2edee8bf3e345c82e2cea0f8dafeffc30496862dd06876ceb'::TEXT, ARRAY[1769]::BIGINT[]),
    (445::BIGINT, 'Cuesta mucho entenderle la materia, llega tarde, parece que le tiene asco a los estudiantes, no es muy amable a la hora de atender dudas ya sea en clase o en consulta, no la recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2019-12-05T00:00:00+00:00'::TIMESTAMPTZ, '8f24cc2b56372ea3849752368961c71076408cbb0aa1779190360ac3e1fb3543'::TEXT, ARRAY[1742]::BIGINT[]),
    (445::BIGINT, 'Me parece una excelente profesional, se nota que sabe mucho de lo que habla, a veces va muy rápido entonces hay que ponerle atención. Si ve que usted le pone, ayuda mucho y es accesible.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-10-24T00:00:00+00:00'::TIMESTAMPTZ, '874c5a38cbf875f4dacded00c10f01169ea8790bac2d4a55d920929839ddc34d'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'La profe es graciosa, no tiene muy buen trato hacia los estudiantes, pero se pasa fácil el curso porque deja bastantes trabajos y explica muy bien en clase'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2019-09-20T00:00:00+00:00'::TIMESTAMPTZ, '43ff7525dac8180a9839af85d74f39d05dc16305198284d2cd1e6638ac5985a8'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'No es muy respetuosa cuando uno pregunta algo. En clase la mayor parte del tiempo es clara y hace muchos ejemplos. El examen se parece a lo visto en tareas y en clase. En los proyectos da mucha retroalimentación útil. Siempre llega tarde.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '91a908f2dc7e93ef18bd39d91758dea1fe2bdfc36ee6576af7d75e21dc55a0ed'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'Para el I semestre del 2019 ella tenia mucho de no dar proba 1, por lo que le cuesta demasiado transmitir el conocimiento, explica masomenos, pura diapositiva, inconsistencia a la hora de calificar (a unos bueno y a otro malo, la misma respuesta), está media loca, llega tarde y no ayuda, mala.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '2ba6c2c0b05b1dcba2d646fff29cabbf8835cf5f96a7c7dee6fb1a265ac4af68'::TEXT, ARRAY[1728]::BIGINT[]),
    (445::BIGINT, 'Explica regular, si se pone atención se le entiende. Sin embargo es muy poco accesible, no responde a las dudas y es muy grosera. Los examenes son faciles y si estudia lo suficiente es pasable'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '737629ba6b40207c85fd8904502fa285c9338b86a585f02a9226a98cfff05472'::TEXT, ARRAY[1728]::BIGINT[]),
    (445::BIGINT, 'Un curso obsoleto y demasiado facil, la profe ayuda bastante si está de buen humor, está medio loca. Se pasa con buena nota si hace todas las tareas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, '5588d1b07d745c8721876b092c6c2dc723c1e7ae209f73172528a04d8b5aafef'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'El curso es muy fácil y la profe deja todo claro, las evaluaciones son fáciles pero son bastantes; por lo que no hay que descuidarse con eso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '6445f81fb4823b54801c7d569a18dd62cf9d24ffc90d5567cab102286f417f79'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'Los exámenes y quices son fáciles. Deja tareas todas las semanas lo cual ayuda a llevar la materia al día, y avisa cada vez que hay quiz. A veces se confunde sola, pero sí se le entiende y la clase se pasa rápido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'a0c5853b8cdee876f4f41d91b176a265094ab8119d0c25b87a2ebf053f5bfef9'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'El curso es fácil de pasar, la profe califica suave pero si está un poco transtornada pareciera que le tiene asco a los estudiantes y en consulta si es grosera de todas formas si la recomiendo'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'b92be2b739c5199b5905730159fc82ef265dd5e43ff608341fd9406175380755'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'Las clases son súper aburridas, da la clase sin ganas hasta se pone a bostezar, deja tareas todas las semanas, pero sirven para el examen. Los exámenes son súper largos, pero fáciles. Califica suave, si la recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '1b186fd8cccf085b70a7070524d4cb30a2be555149feca07838db21c5e122be9'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'No se le entiende muy bien la materia, no ayuda mucho en consulta'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '34ec7862c2a70f3bdc72e9cb4b34022c15702487887c345200c58bdb4aca8028'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'Se nota que sabe bastante, pero no sabe transmitirlo. Con ella el curso es muy pasable y uno sí aprende, solo que su actitud no es la mejor, en consulta es grosera.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'eac2ed8d5a2e33956bcfec25dd4bc0f77e77e324ba46516f5bb2b7d259dfbf26'::TEXT, ARRAY[1746, 1769]::BIGINT[]),
    (445::BIGINT, 'Excelente profesora, los quices y tareas ayudan al examen, con los proyectos se aprende la aplicación de esos temas a la vida real. Es sencillo de pasar, solo hay que dedicar un espacio para hacer tareas de ahi en fuera es muy facil y se aprende demasiado en el curso. Recomendada 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Muchos exámenes']::TEXT[], '2017-07-30T00:00:00+00:00'::TIMESTAMPTZ, '1b81c2258663df77111dcdcdbf074d80c6aba9a89b8dbd4ffb73eb98f70b3c94'::TEXT, ARRAY[1746]::BIGINT[]),
    (445::BIGINT, 'Deja tareas y quices todas las semanas pero las tareas ayudan a la hora de hacer los quices porque son similares. Hace 2 proyectos enfocados a la materia (son sencillos) y los exámenes son muy largos. A veces no se le entiende lo que explica, pero la mayoría del tiempo maneja la materia.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'bbfebe15e18ccd7d470e9ff77b4101fc32f080dc4cf92179810840ea628a7f56'::TEXT, ARRAY[1746, 1769]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
